style.css:
@-moz-document domain("pinterest.com") {
/* Fond général sombre */
  body, html {
    background-color: #0d0d0d !important;
    color: #e6e6e6 !important;
  }

  /* En-tête et barre de navigation */
  header,
  [data-test-id="header"],
  input[type="search"],
  [role="search"] {
    background-color: #1a1a1a !important;
    color: #ffffff !important;
    border: none !important;
  }

  /* Blocs de pins et tableaux */
  div[data-test-id*="board"],
  div[data-test-id*="pin"],
  .gridCentered,
  .Collection-Item,
  .Board-Item {
    background-color: #1a1a1a !important;
    border-radius: 10px;
    box-shadow: 0 0 10px rgba(139, 0, 0, 0.4) !important;
  }

  /* Titres, textes et liens */
  h1, h2, h3, h4, h5, h6,
  span, p, a {
    color: #e6e6e6 !important;
  }

  a:hover,
  button:hover {
    color: #ff4d4d !important;
    background-color: #260000 !important;
  }

  /* Menu latéral gauche */
  nav,
  .Jea {
    background-color: #121212 !important;
    border-right: 1px solid #330000 !important;
  }

  /* Boutons */
  button,
  .Button,
  .button {
    background-color: #330000 !important;
    color: #fff !important;
    border-radius: 6px !important;
    border: none !important;
  }

  button:hover {
    background-color: #4d0000 !important;
  }

  /* Scrollbar personnalisée */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #1a1a1a;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #8b0000;
    border-radius: 10px;
  }

  /* Supprimer les fonds blancs restants */
  [style*="background-color: white"],
  [style*="background-color:#fff"] {
    background-color: #1a1a1a !important;
  }

  /* Couleurs d’icônes actives ou en survol */
  svg,
  svg path {
    fill: #e6e6e6 !important;
  }

  svg:hover,
  svg path:hover {
    fill: #ff3333 !important;
  }
}
